154	/// Builds display rows from a snapshot and marks stale data by capture age.
155	///
156	/// Callers should pass `Local::now()` for `now` at render time; using a cached timestamp can make
157	/// fresh data appear stale or prevent stale warnings from appearing.
158	pub(crate) fn compose_rate_limit_data(
159	    snapshot: Option<&RateLimitSnapshotDisplay>,
160	    now: DateTime<Local>,
161	) -> StatusRateLimitData {
162	    match snapshot {
163	        Some(snapshot) => compose_rate_limit_data_many(std::slice::from_ref(snapshot), now),
164	        None => StatusRateLimitData::Missing,
165	    }
166	}
167	
168	pub(crate) fn compose_rate_limit_data_many(
169	    snapshots: &[RateLimitSnapshotDisplay],
170	    now: DateTime<Local>,
171	) -> StatusRateLimitData {
172	    if snapshots.is_empty() {
173	        return StatusRateLimitData::Missing;
174	    }
175	
176	    let mut rows = Vec::with_capacity(snapshots.len().saturating_mul(3));
177	    let mut stale = false;
178	
179	    for snapshot in snapshots {
180	        stale |= now.signed_duration_since(snapshot.captured_at)
181	            > ChronoDuration::minutes(RATE_LIMIT_STALE_THRESHOLD_MINUTES);
182	
