62	fn sanitize_directory(lines: Vec<String>) -> Vec<String> {
63	    lines
64	        .into_iter()
65	        .map(|line| {
66	            if let (Some(dir_pos), Some(pipe_idx)) = (line.find("Directory: "), line.rfind('│')) {
67	                let prefix = &line[..dir_pos + "Directory: ".len()];
68	                let suffix = &line[pipe_idx..];
69	                let content_width = pipe_idx.saturating_sub(dir_pos + "Directory: ".len());
70	                let replacement = "[[workspace]]";
71	                let mut rebuilt = prefix.to_string();
72	                rebuilt.push_str(replacement);
73	                if content_width > replacement.len() {
74	                    rebuilt.push_str(&" ".repeat(content_width - replacement.len()));
75	                }
76	                rebuilt.push_str(suffix);
77	                rebuilt
78	            } else {
79	                line
80	            }
81	        })
82	        .collect()
83	}
